const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),time=s=>{s=Math.max(0,Math.floor(s||0));return `${Math.floor(s/60)}:${String(s%60).padStart(2,'0')}`;},size=n=>n>=1e9?(n/1e9).toFixed(2)+' GB':(n/1e6).toFixed(1)+' MB';
const defaults={...DEFAULT_PREFERENCES,quality:'eco',targetFPS:60,hdrMode:'off',musicOnly:false,eqLow:0,eqMid:0,eqHigh:0,wifiOnly:true,cacheMB:128,downloadFormat:'original',sfx:true,visualSyncAuto:false,bloom:.18,mobileBloomVersion:1};
function phonePreferences(saved={}){const p=preferencesWithDefaults({...defaults,...saved});if(saved.mobileBloomVersion!==1&&Number(p.bloom)===DEFAULT_PREFERENCES.bloom)p.bloom=defaults.bloom;p.mobileBloomVersion=1;return p;}
const audio=new NativeAudio(),reactor=new MobileReactor(audio),feedback=new Feedback(audio);
installBrand();installSettingSliderGestures();
const state={tracks:[],sources:[],playlists:[],prefs:{...defaults},view:'',filter:'all',search:'',sort:'playlist',active:true,limit:60,detail:null,destination:{},revision:0,previewRevision:0,jobs:{scan:{},downloads:{}}};
let saveTimer,analysisTimer,statusTimer,selectedDownloads=[],discoveryId='',artKey='',pollGeneration=0,discovering=false;
const current=()=>state.tracks.find(t=>t.id===audio.snapshot.id),toast=message=>{const host=$('#sheet').open?$('#sheet'):document.body;host.append($('#toasts'));const n=document.createElement('div');n.className='toast';n.textContent=message;$('#toasts').append(n);setTimeout(()=>n.remove(),5000);},safe=fn=>(...args)=>{try{return Promise.resolve(fn(...args)).catch(e=>toast(e.message));}catch(e){toast(e.message);}};
installAppUpdateUI({request:(action,preferences)=>rpc('appUpdate',{action,preferences}),host:()=>$('#app-update-slot'),active:()=>state.view==='settings',toast,platform:'android'});
const sona=installDanceCompanion({reactor,audio,savePosition:position=>preferences({dancePosition:position}),onError:()=>toast('Sona could not load. Try reopening the app.')});
const palette=new ArtworkPalette({read:async key=>JSON.parse(localStorage.getItem('palette:'+key)||'null'),write:async(key,colors)=>{localStorage.setItem('palette:'+key,JSON.stringify({version:2,colors}));if(localStorage.length>150){for(const key of Object.keys(localStorage).filter(k=>k.startsWith('palette:')).slice(0,20))localStorage.removeItem(key);}},decode:decodeArtwork,onChange:colors=>{reactor.coverColors=colors;applyInterfaceAccent(colors,true);}});
const cover=t=>t?.artwork?`<img class="cover" src="/artwork/${encodeURIComponent(t.artwork)}" alt="" loading="lazy">`:'<span aria-hidden="true">♫</span>';
document.addEventListener('error',e=>{if(e.target instanceof HTMLImageElement&&e.target.classList.contains('cover'))e.target.hidden=true;},true);
function sheet(title,html,view){state.view=view;$('#sheet-back').hidden=!['sources','online','sync','matches','details','recordings','lyrics','playlist','credits','license'].includes(view);$('#sheet-title').textContent=title;$('#sheet-body').onclick=null;$('#sheet-body').innerHTML=html;$('#sheet-body').scrollTop=0;if(!$('#sheet').open)$('#sheet').showModal();}
function close(){if($('#sheet').open)$('#sheet').close();state.view='';}
$('#sheet').addEventListener('close',()=>{state.view='';document.body.append($('#toasts'));});
function back(){const parents={sources:library,online:sources,sync:sources,matches:sync,details:library,recordings:()=>details(state.detail),lyrics:()=>details(state.detail),playlist:library,credits:settings,license:actions.credits};return parents[state.view]?safe(parents[state.view])():close();}
window.mobileBack=()=>{if($('#sheet').open){back();return true;}if(document.body.classList.contains('immersed')){actions.immerse();return true;}return false;};$('#sheet-back').onclick=back;$('#sheet-close').onclick=close;$('#sheet').addEventListener('click',e=>{if(e.target===$('#sheet'))close();});
function apply(){const p=state.prefs;for(const k of ['quality','targetFPS','hdrMode','mode','intensity','dynamicVisuals','coverPalette','particleColor','responsiveness','fluidity','iridescence','depth','spectralDetail','kaleidoscope','kaleidoscopeMode','autoDirection','rollercoaster','cameraSpeed','cameraZoom'])reactor[k]=p[k];reactor.appearance={...reactor.appearance,...p};reactor.visualTheme=p.visualTheme;reactor.setVisualSync(p);document.body.classList.toggle('music-only',p.musicOnly);reactor.setMusicOnly(p.musicOnly);$('#music-only').setAttribute('aria-pressed',String(p.musicOnly));$('#music-only').innerHTML=p.musicOnly?'✧<span>Show visualizer</span>':'◉<span>Music only</span>';sona.apply({...p,musicOnly:p.musicOnly||!state.active});feedback.apply({...p,musicOnly:p.musicOnly||!state.active});void rpc('visuals',{enabled:state.active&&!p.musicOnly}).catch(()=>{});}
function preferences(patch){if(patch.musicOnly)void rpc('captureStop').catch(()=>{});Object.assign(state.prefs,patch);apply();syncPreferenceControls(patch);clearTimeout(saveTimer);saveTimer=setTimeout(()=>void rpc('preferences',state.prefs).catch(e=>toast(e.message)),350);}
async function refresh(initial=false){const data=await rpc('library');Object.assign(state,{tracks:data.tracks,sources:data.sources,playlists:data.playlists,destination:data.destination||{},revision:data.revision});if(initial)state.prefs=phonePreferences(data.preferences);reactor.displayRefreshRate=data.displayHz||60;$('#welcome').hidden=state.tracks.length>0;document.body.classList.toggle('empty-library',!state.tracks.length);renderNow();return data;}
function renderNow(){const t=current();$('#now-title').textContent=t?.title||'Find your frequency';$('#now-artist').textContent=t?.artist||'Your music, wherever you are';$('#now-art').innerHTML=cover(t);$('#music-only-title').textContent=t?.title||'Your pocket universe';$('#music-only-artist').textContent=t?.artist||'';$('#music-only-cover').innerHTML=cover(t);$('#favorite').textContent=t?.favorite?'♥':'♡';$('#favorite').setAttribute('aria-pressed',String(!!t?.favorite));$('#favorite').disabled=!t;
 if(reactor.songId!==t?.id){reactor.songId=t?.id;reactor.songProfile=null;void loadSongProfile(t?.id);}
 const key=t?.id+':'+t?.artwork;if(key!==artKey){artKey=key;document.documentElement.style.setProperty('--cover-image',t?.artwork?`url('/artwork/${encodeURIComponent(t.artwork)}')`:'none');void palette.select(t?.artwork);reactor.character.select(createTrackCharacter(t||{}),String(Date.now()));}
}
async function loadSongProfile(id){if(!id)return;try{const value=await rpc(needsSongAnalysis(state.prefs)?'analyzeSong':'songProfile',{id});if(current()?.id!==id)return;reactor.songProfile=value.profile;if(!value.profile&&!value.error&&value.job?.running)setTimeout(async()=>{if(current()?.id!==id)return;const result=await rpc('songProfile',{id}).catch(()=>null);if(result?.profile)reactor.songProfile=result.profile;else if(!result?.error)void loadSongProfile(id);},3000);}catch{}}
function renderPlayback(){const s=audio.snapshot;reactor.desktopSource=s.capturing?{}:null;feedback.desktopListening=!!s.capturing;for(const id of ['seek','volume','next','previous','shuffle','repeat','volume-value'])$('#'+id).disabled=!!s.capturing;$('#play').textContent=audio.paused?'▶':'Ⅱ';$('#play').setAttribute('aria-label',audio.paused?'Play':'Pause');$('#shuffle').setAttribute('aria-pressed',String(!!s.shuffle));$('#repeat').setAttribute('aria-pressed',String(s.repeat===1));$('#elapsed').textContent=time(audio.currentTime);$('#duration').textContent=time(audio.duration);if(document.activeElement!==$('#seek'))$('#seek').value=audio.duration?audio.currentTime/audio.duration*1000:0;if(document.activeElement!==$('#volume'))$('#volume').value=audio.volume*100;$('#volume-value').textContent=Number((audio.volume*100).toFixed(1))+'%';$('#playback-problem').hidden=!s.error;$('#playback-problem-message').textContent=s.error||'';$('#playback-status').textContent=s.captureError|| (s.capturing?'Listening to other apps':s.buffering?'Loading audio…':'');}
audio.addEventListener('trackchange',()=>{reactor.resetAnalysis();renderNow();if(state.view==='queue')void queue();const t=current();if(t&&discoveryId!==t.id){discoveryId=t.id;void rpc('research',{id:t.id}).then(updated=>{Object.assign(t,updated);if(current()?.id===t.id){artKey='';renderNow();}}).catch(()=>{});}});audio.addEventListener('timeupdate',renderPlayback);
async function poll(generation=++pollGeneration){if(!state.active||generation!==pollGeneration)return;try{const s=await rpc('state');if(generation!==pollGeneration)return;if(s.capturing!==audio.snapshot.capturing)reactor.resetAnalysis();audio.update(s);}catch{}if(state.active&&generation===pollGeneration)analysisTimer=setTimeout(()=>poll(generation),400);}
window.mobileActive=active=>{state.active=active;feedback.apply({...state.prefs,musicOnly:state.prefs.musicOnly||!active});pollGeneration++;clearTimeout(analysisTimer);sona.apply({...state.prefs,musicOnly:state.prefs.musicOnly||!active});void reactor.foreground(active);if(active)void poll();};document.addEventListener('visibilitychange',()=>window.mobileActive(!document.hidden));
function tracks(){let ts=state.tracks.filter(t=>t.available!==false);if(state.filter==='favorites')ts=ts.filter(t=>t.favorite);else if(state.filter==='downloaded')ts=ts.filter(t=>t.downloaded);else if(state.filter==='mixes')ts=ts.filter(t=>t.kind==='mix');else if(state.filter.startsWith('source:'))ts=ts.filter(t=>t.sourceId===state.filter.slice(7)||Object.hasOwn(t.sourceOrders||{},state.filter.slice(7)));else if(state.filter.startsWith('playlist:')){const p=state.playlists.find(p=>p.id===state.filter.slice(9));ts=ts.filter(t=>p?.tracks.includes(t.id));}else if(state.filter.startsWith('genre:'))ts=ts.filter(t=>(t.genre||'').split(/[,;]/).some(g=>g.trim()===state.filter.slice(6)));
 const sourceOrder=t=>state.filter.startsWith('source:')?(t.sourceOrders?.[state.filter.slice(7)]??t.playlistIndex??999999):(t.playlistIndex??999999);const selectedPlaylist=state.playlists.find(p=>'playlist:'+p.id===state.filter);if(selectedPlaylist&&state.sort==='playlist')ts.forEach(t=>t.mobileOrder=selectedPlaylist.tracks.indexOf(t.id));const query=state.search.toLocaleLowerCase();ts=ts.filter(t=>[t.title,t.artist,t.album,t.genre].join(' ').toLocaleLowerCase().includes(query));return ts.sort((a,b)=>state.sort==='title'?a.title.localeCompare(b.title):state.sort==='artist'?(a.artist||'').localeCompare(b.artist||''):state.sort==='recent'?(b.lastPlayed||0)-(a.lastPlayed||0):state.sort==='plays'?(b.plays||0)-(a.plays||0):state.sort==='added'?(b.addedAt||0)-(a.addedAt||0):selectedPlaylist?(a.mobileOrder-b.mobileOrder):sourceOrder(a)-sourceOrder(b));
}
function trackRows(ts){return ts.map(t=>`<div class="track ${t.id===audio.snapshot.id?'current':''}"><button class="track-play" data-play="${esc(t.id)}" aria-label="Play ${esc(t.title)}"><span class="art">${cover(t)}<span class="art-play" aria-hidden="true">▶</span></span><span class="name"><strong>${esc(t.title)}</strong><small>${esc(t.artist||'Artist unknown')}</small></span><time>${time(t.duration)}</time></button><button class="round" data-details="${esc(t.id)}" aria-label="Details for ${esc(t.title)}">⋯</button></div>`).join('');}
function results(){const ts=tracks();$('#results').innerHTML=trackRows(ts.slice(0,state.limit))+(ts.length>state.limit?'<button class="secondary" data-action="more">Show more tracks</button>':'')||(state.tracks.length?'<div class="empty"><p>No songs match this view.</p><button class="secondary" data-action="all-music">Show all my music</button><button class="text" data-action="sync">View playlist downloads</button></div>':'<div class="empty"><p>No music here yet.</p><button class="primary" data-action="sources">Add music</button><button class="text" data-action="sync">View playlist downloads</button></div>');$('#result-count').textContent=ts.length.toLocaleString()+' song'+(ts.length===1?'':'s');$('#library-play-all').disabled=!ts.length;}
function listen(){state.search='';state.filter=state.tracks.some(t=>t.downloaded&&t.available!==false)?'downloaded':'all';state.limit=60;library();}
function library(){const genres=[...new Set(state.tracks.flatMap(t=>(t.genre||'').split(/[,;]/).map(g=>g.trim()).filter(Boolean)))].sort();sheet('Your library',`<div class="toolbar"><input id="search" type="search" placeholder="Song, artist, album, genre…" aria-label="Search music" value="${esc(state.search)}"><button class="round" data-action="sources" aria-label="Add music">＋</button></div><div class="pills">${[['all','All music'],['downloaded','Downloaded'],['favorites','Favorites'],['mixes','Long mixes'],...state.sources.map(s=>['source:'+s.id,s.name]),...state.playlists.map(p=>['playlist:'+p.id,p.name])].map(([id,label])=>`<button class="pill ${state.filter===id?'active':''}" data-filter="${esc(id)}">${esc(label)}</button>`).join('')}</div><div class="toolbar"><select id="sort" aria-label="Sort music">${[['playlist','Playlist order'],['title','Title'],['artist','Artist'],['recent','Recently played'],['plays','Most played'],['added','Newest first']].map(([id,label])=>`<option value="${id}" ${state.sort===id?'selected':''}>${label}</option>`).join('')}</select><select id="genre" aria-label="Filter genre"><option value="">Every genre</option>${genres.map(g=>`<option ${state.filter==='genre:'+g?'selected':''}>${esc(g)}</option>`).join('')}</select></div><div class="library-playbar"><small id="result-count"></small><button class="primary" id="library-play-all" data-action="play-all"><span aria-hidden="true">▶</span> Play all</button></div><p class="library-hint">Tap a cover or song to play. ⋯ opens details.</p><div id="library-jobs"></div><div id="results"></div><button class="text" data-action="playlist-create">＋ Make a playlist</button>`,'library');results();renderLibraryJobs();$('#search').oninput=e=>{state.search=e.target.value;state.limit=60;results();};$('#sort').onchange=e=>{state.sort=e.target.value;results();};$('#genre').onchange=e=>{state.filter=e.target.value?'genre:'+e.target.value:'all';results();};}
async function play(id,fromQueue){if(fromQueue){const request=queuePlaybackRequest(audio.snapshot,id);if(request){const snapshot=await rpc('play',request);close();audio.update(snapshot);return;}}let ids=fromQueue?audio.snapshot.queue:tracks().map(t=>t.id);if(!ids.includes(id))ids=[id,...state.tracks.map(t=>t.id).filter(x=>x!==id)];if(ids.length===1)ids.push(...state.tracks.filter(t=>t.id!==id&&t.available!==false).map(t=>t.id));const snapshot=await rpc('play',{queue:ids,index:ids.indexOf(id),position:state.tracks.find(t=>t.id===id)?.kind==='mix'?(state.tracks.find(t=>t.id===id)?.position||0)*1000:0});close();audio.update(snapshot);}
async function playbackDetails(){
 sheet('Playback details','<p class="notice" role="status">Checking the saved file on your phone…</p>','playback-details');
 const d=await rpc('playbackDetails');if(state.view!=='playback-details')return;
 const streams=d.audioStreams?.join(', '),bytes=d.actualBytes>=0?size(d.actualBytes):'Not reported by folder';
 $('#sheet-body').innerHTML=`<div class="stack"><h3>${esc(d.title||'Selected song')}</h3><p class="notice">${esc(d.error||'File check complete. Tap Try again to restart playback.')}</p><div class="details-grid">${[['Saved in',d.location],['File access',d.readable?'Readable':'Cannot read'],['File size',bytes],['Audio detected',streams||d.format||'Unknown'],['Player error',d.errorCode||'None'],['App version',d.appVersion]].map(([k,v])=>`<span class="muted">${k}<b>${esc(v)}</b></span>`).join('')}</div>${d.pathRepaired?'<p class="notice">Reconnected the existing file in app storage. Try playing it again.</p>':''}${d.fileError||d.formatNotice?`<p class="error">${esc(d.fileError||d.formatNotice)}</p>`:''}<button class="primary" data-action="playback-retry">Try again</button><button class="secondary" data-action="copy-playback-details">Copy diagnostic details</button><p class="muted">These details stay on your phone. Copy them if you want to share the error for troubleshooting.</p><details><summary>Technical details</summary><pre class="playback-diagnostics">${esc([d.fileName,d.path,d.device,d.errorDetails].filter(Boolean).join('\n\n'))}</pre></details></div>`;
}
async function queue(){const origin=state.view,history=await rpc('history');if(state.view!==origin)return;const s=audio.snapshot,ts=upcomingIds(s).map(id=>state.tracks.find(t=>t.id===id)).filter(Boolean);const previous=(history.items||[]).slice(0,-1).slice(-8).reverse().map(h=>state.tracks.find(t=>t.id===h.id)).filter(Boolean);sheet('Your listening queue',`<p class="notice">${s.repeat===1?'Repeat track is on. Turn it off to continue through the queue.':s.shuffle?'Songs below follow the shuffled playback order, including with the screen off.':'Your queue continues when the screen is off and loops when it reaches the end.'}</p>${previous.length?'<h3 class="section-label">PLAYED BEFORE</h3>'+trackRows(previous):''}<h3 class="section-label">NOW & NEXT${s.shuffle?' · SHUFFLE ON':''}</h3>${trackRows(ts)||'<p class="empty">Choose a song to begin.</p>'}`,'queue');}
function toggle(label,key){return `<label class="setting"><span><span class="setting-title">${label}</span><input type="checkbox" data-pref="${key}" ${state.prefs[key]?'checked':''} aria-label="${label}"></span></label>`;}
function slider(label,key,min,max,step=0.05){return `<label class="setting"><span><span class="setting-title">${label}</span><output data-value="${key}">${state.prefs[key]}</output><button class="reset" type="button" data-reset="${key}" aria-label="Reset ${label}">↺</button></span><input type="range" data-pref="${key}" min="${min}" max="${max}" step="${step}" value="${state.prefs[key]}" aria-label="${label}"></label>`;}
function select(label,key,options){return `<label class="setting"><span>${label}<button class="reset" type="button" data-reset="${key}" aria-label="Reset ${label}">↺</button></span><select data-pref="${key}" aria-label="${label}">${options.map(([id,l])=>`<option value="${id}" ${String(state.prefs[key])===String(id)?'selected':''}>${l}</option>`).join('')}</select></label>`;}
function visuals(){sheet('Visual character',`<p class="notice">Balanced detail and 60 FPS keep phone heat and battery use in check. Drag sliders sideways to adjust; swipe up or down to scroll.</p>${toggle('Track character','autoDirection')}<p class="muted">Saved audio analysis guides evolving forms, texture and energy chapters. Live sound keeps the immediate response. Behind the sound → Listening edit shows the song map.</p>${slider('Musical flashes','flash',0,2)}${slider('Contrast','contrast',.5,2)}${slider('Movement','motionAmount',0,4)}${slider('Beat motion','beatMotion',0,3)}${slider('Response','responsiveness',.25,8)}${select('Detail','quality',[['eco','Balanced · phone default'],['auto','Adaptive'],['high','High · more battery & heat']])}${select('Frame rate','targetFPS',[[30,'30 FPS · battery saver'],[60,'60 FPS · balanced'],[120,'120 FPS · smooth'],['auto','Match display']])}${select('HDR output','hdrMode',[['off','Off · standard output'],['auto','Auto · if supported'],['on','Try HDR']])}<p id="hdr-status" class="muted">Availability depends on Android System WebView and the display.</p>${toggle('Rollercoaster camera','rollercoaster')}${slider('Rail speed','cameraSpeed',CAMERA_SPEED.min,CAMERA_SPEED.max,.01)}${toggle('Camera zoom','cameraZoom')}<p class="muted">Bass and loudness draw you into the particles. The view widens as you move closer, then opens back out in quiet moments.</p><button class="text" data-action="camera-reset">Reset view</button>${toggle('Kaleidoscope','kaleidoscope')}${select('Pattern','kaleidoscopeMode',KALEIDOSCOPE_MODES.map(m=>[m.id,m.label]))}${toggle('Sona','danceCompanion')}<button class="text" data-action="sona-reset">Reset Sona’s position</button>`,'visuals');}
async function settings(){sheet('Make yourself at home',`<div class="stack"><div class="card"><h3>Your music</h3><button class="secondary" data-action="metadata-review">Review missing & uncertain details</button><button class="secondary" data-action="sources">Music sources & playlist updates</button><button class="secondary" data-action="scan">Rescan local folders</button><button class="secondary" data-action="genre-discovery">${discovering?'Pause discovery':'Find missing genres & details'}</button></div><div class="card"><h3>Space & downloads</h3>${toggle('Wi-Fi downloads only','wifiOnly')}${select('Download quality','downloadFormat',[['original','Original compressed audio · recommended'],['compact','Opus 128 kb/s · about 1 MB/min']])}<p>Existing files stay in their original quality. Compact mode only converts new downloads. Converting YouTube audio to FLAC cannot restore lost detail.</p>${select('Artwork cache limit','cacheMB',[[64,'64 MB'],[128,'128 MB · default'],[256,'256 MB'],[512,'512 MB']])}<div id="storage" class="muted">Measuring storage…</div><button class="text" data-action="clear-cache">Clear cached covers</button><p>This only removes replaceable artwork. Your audio files, metadata and listening history are kept.</p></div><div class="card"><h3>Screen-off listening</h3><p>Playback continues when you lock the phone or open another app. Use the media controls on your lock screen or pull down Quick Settings for play, pause and skipping songs. Expanded controls also offer volume − / + when supported by your phone.</p><p>Your phone’s volume buttons control music. Visuals rest in the background to save battery.</p><button class="secondary" data-action="notification-settings">Notification settings</button><p>If Samsung stops playback, open App settings → Battery → Unrestricted, and check that Resonance isn’t in Sleeping apps.</p><button class="text" data-action="background-settings">Open app settings</button></div>${listeningSettings(state.prefs,{mobile:true})}<div class="card"><h3>Sound & timing</h3><button class="secondary" data-action="playback-details">Check playback & saved file</button><button class="secondary" data-action="capture">${audio.snapshot.capturing?'Stop listening to other apps':'Listen to other apps'}</button><p>Android asks for audio-capture consent each time. Only apps that allow capture can be visualized; no audio is recorded. Local playback pauses while listening.</p>${slider('Low EQ · dB','eqLow',-12,6,1)}${slider('Mid EQ · dB','eqMid',-12,6,1)}${slider('High EQ · dB','eqHigh',-12,6,1)}<p>Zero bypasses the equalizer. Boosting can clip; prefer small cuts.</p>${slider('Bluetooth visual offset · ms','visualSyncOffsetMs',0,1000,1)}<label class="field">Exact offset · milliseconds<input type="number" inputmode="numeric" min="0" max="1000" step="1" value="${state.prefs.visualSyncOffsetMs}" data-offset-number></label><p>If your headphones sound late, increase the visual offset. This delays the visuals without changing playback. Android does not report a reliable end-to-end Bluetooth delay here.</p>${toggle('Interface sounds','sfx')}${slider('Interface sound volume','sfxVolume',0,1,.01)}</div><div id="app-update-slot"></div><div class="card"><h3>Good to know</h3><p>One-finger swipes on the visualizer rotate the scene in any direction, including while Rollercoaster is on. Two-finger swipes on the background: left / right changes songs; up / down seeks by 10 seconds. Drag Sona to move her. In settings, drag sliders sideways to adjust; swipe vertically to scroll. In Library, tap a cover or song to play; ⋯ opens details. The artwork in the bottom player also opens song details. The system volume buttons always work.</p><p>Music keeps playing with the screen locked. Visuals and Sona rest when the app is in the background.</p><button class="text" data-action="credits">Open-source acknowledgements</button><p>Resonance Android · 0.2.0 preview<br>Based on the approved desktop checkpoint of 15 October 2026.</p><button class="text" data-action="update-engine">Update playlist downloader</button></div></div>`,'settings');const s=await rpc('storage');if(state.view==='settings')$('#storage').innerHTML=`<div class="details-grid">${[['Downloaded music',s.downloaded],['Linked music · no copies',s.linked],['Cover cache',s.artwork],['Library database',s.database],['Download tools',s.tools],['APK',s.application],['Free space',s.free]].map(([l,n])=>`<span>${l}<b>${size(n)}</b></span>`).join('')}</div>`;}
function sources(){sheet('Add music',`<div class="stack"><p class="muted">Choose where your songs come from.</p><button class="source-choice" data-action="folder"><b>♫</b><span><strong>Add existing music</strong><small>Read audio files already on your phone.</small></span><span>›</span></button><button class="source-choice" data-action="online"><b>↓</b><span><strong>Download a playlist</strong><small>Paste a link, choose a folder, save the songs.</small></span><span>›</span></button><button class="secondary" data-action="sync">Downloads & playlist updates</button><h3 class="section-label">CONNECTED SOURCES</h3>${state.sources.map(source=>{const count=state.tracks.filter(t=>t.sourceId===source.id||Object.hasOwn(t.sourceOrders||{},source.id)).length;return `<div class="card"><h3>${esc(source.name)}</h3><p>${source.type==='folder'?'Local folder':source.type==='spotify'?'Spotify playlist':'YouTube playlist'} · ${count} songs saved${source.trackCount!==undefined?' · '+source.trackCount+' in playlist':''}</p>${source.lastError?'<p class="error">'+esc(source.lastError)+'</p>':''}${source.type==='folder'&&count===0?'<p>This folder has no imported audio. To save online music here, choose it as the destination in Downloads.</p>':''}<div class="toolbar">${source.type==='folder'?'<button class="secondary" data-action="scan">Find local songs</button>':`<button class="secondary" data-check-source="${esc(source.id)}">Check for new songs</button>`}<button class="text" data-disconnect="${esc(source.id)}">Disconnect</button></div></div>`;}).join('')||'<p class="muted">Your folders and playlists will appear here.</p>'}</div>`,'sources');}
function online(){sheet('Download a playlist',`<form id="source-form" class="stack"><p class="notice">Paste a public YouTube, YouTube Music or Spotify playlist. We’ll show its songs before downloading.</p><label class="field">Playlist link<input name="url" required type="url" inputmode="url" autocomplete="off" placeholder="https://music.youtube.com/playlist?list=…"></label><label class="field">Name · optional<input name="name" placeholder="Use the playlist’s name"></label><p id="source-error" class="error" role="alert" hidden></p><button class="primary">Find playlist songs</button><p class="muted">Spotify supplies the song list. You choose matching YouTube recordings to download.</p><p class="muted">No music is downloaded until you choose Download songs.</p></form>`,'online');$('#source-form').onsubmit=safe(async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;button.textContent='Connecting…';try{const data=Object.fromEntries(new FormData(e.target));data.url=data.url.trim();data.name=data.name.trim();data.type=new URL(data.url).hostname==='open.spotify.com'?'spotify':'youtube';data.customName=!!data.name;const source=await rpc('source',data);await refresh();await sync();await checkPlaylists(source.id);}catch(error){if(state.view==='online'){$('#source-error').hidden=false;$('#source-error').textContent=error.message;}throw error;}finally{button.disabled=false;button.textContent='Find playlist songs';}});}
async function checkPlaylists(sourceId=''){if(!state.sources.some(s=>s.type!=='folder')){online();return;}state.jobs.downloads=await rpc('syncCheck',{sourceId});renderSyncStatus();await refreshJobs();}
